function treeFromFlat(files:Map<string,Entry>):string { type Node={files:Map<string,Entry>;dirs:Map<string,Node>}; const root:Node={files:new Map(),dirs:new Map()}; for(const [path,e] of files){const parts=path.split('/');let n=root;for(const p of parts.slice(0,-1)){if(!n.dirs.has(p))n.dirs.set(p,{files:new Map(),dirs:new Map()});n=n.dirs.get(p)!;}n.files.set(parts.at(-1)!,e);} const build=(n:Node):string=>{const m=new Map(n.files);for(const [name,d] of n.dirs)m.set(name,{mode:'40000',sha:build(d),type:'tree'});return tree(m);};return build(root); }
